settings.transformLiquid:
{% comment %}
  ============================================================
  GLOBAL SCRIPT — brand tokens (single source of truth)
  Runs once per render, before the template base and modules.
  Reference anywhere in Liquid as {{ global.<key> }}.
  These are FIXED brand values, not marketer-editable inputs.
  ============================================================
{% endcomment %}

{% comment %} --- Colors --------------------------------------- {% endcomment %}
{% set_global blaze = "#E4572E" %}   {% comment %} accent / CTA {% endcomment %}
{% set_global ink = "#1A2420" %}     {% comment %} primary text {% endcomment %}
{% set_global deep = "#22372E" %}    {% comment %} dark surfaces {% endcomment %}
{% set_global paper = "#EEF0EC" %}   {% comment %} light background {% endcomment %}
{% set_global mist = "#E2E7E0" %}    {% comment %} subtle background {% endcomment %}
{% set_global granite = "#5C6660" %} {% comment %} secondary text {% endcomment %}
{% set_global faint = "#8A948D" %}   {% comment %} muted / captions {% endcomment %}
{% set_global line = "#C9D1C6" %}    {% comment %} borders / dividers {% endcomment %}

{% comment %} --- Font stacks ---------------------------------- {% endcomment %}
{% set_global font_heading = "'Archivo','Helvetica Neue',Arial,sans-serif" %}
{% set_global font_body = "'Inter','Helvetica Neue',Arial,sans-serif" %}
